  -- ── 1. SCHEMA ADDITIONS ──────────────────────────────────────
  ALTER TABLE products ADD COLUMN IF NOT EXISTS is_pinned BOOLEAN DEFAULT FALSE;
  ALTER TABLE products ADD COLUMN IF NOT EXISTS sort_order INTEGER DEFAULT 99;
  ALTER TABLE products ADD COLUMN IF NOT EXISTS slug TEXT;
  ALTER TABLE boutiques ADD COLUMN IF NOT EXISTS is_pinned BOOLEAN DEFAULT FALSE;
  ALTER TABLE boutiques ADD COLUMN IF NOT EXISTS sort_order INTEGER DEFAULT 99;

  CREATE UNIQUE INDEX IF NOT EXISTS products_slug_unique ON products(slug) WHERE slug IS NOT NULL;
  CREATE INDEX IF NOT EXISTS idx_products_pinned ON products(main_category_id, is_pinned, sort_order);

  -- ── 2. ORDER_TRACKING TABLE ───────────────────────────────────
  CREATE TABLE IF NOT EXISTS order_tracking (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    order_id UUID REFERENCES orders(id) ON DELETE CASCADE,
    status TEXT NOT NULL DEFAULT 'pending',
    title TEXT,
    description TEXT,
    location TEXT DEFAULT 'Shamim Forever HQ, Pakistan',
    created_at TIMESTAMPTZ DEFAULT NOW()
  );
  CREATE INDEX IF NOT EXISTS idx_order_tracking_order ON order_tracking(order_id);
  ALTER TABLE order_tracking ENABLE ROW LEVEL SECURITY;
  DROP POLICY IF EXISTS "order_tracking_all" ON order_tracking;
  CREATE POLICY "order_tracking_all" ON order_tracking FOR ALL USING (TRUE);

  -- ── 3. INNER CIRCLE APPLICATIONS TABLE ───────────────────────
  CREATE TABLE IF NOT EXISTS inner_circle_applications (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    wallet_address TEXT,
    order_ref TEXT,
    total_usd NUMERIC(10,2) DEFAULT 0,
    phone TEXT,
    status TEXT DEFAULT 'pending',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
  );
  ALTER TABLE inner_circle_applications ENABLE ROW LEVEL SECURITY;
  DROP POLICY IF EXISTS "ica_all" ON inner_circle_applications;
  CREATE POLICY "ica_all" ON inner_circle_applications FOR ALL USING (TRUE);

  -- ── 4. MAIN CATEGORIES (fixed UUIDs — hardcoded in shop page) ─
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

  -- ── 5. SUB-CATEGORIES (fixed UUIDs — hardcoded in shop page) ──
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

  -- ── 6. COLLECTIONS ─────────────────────────────────────────────
  ON CONFLICT (slug) DO NOTHING;

  -- ── 7. DELETE OLD PRODUCTS (clean start) ────────────────────────
  -- Comment this out if you want to KEEP existing products
  TRUNCATE TABLE products CASCADE;

